"""Offline scrolling chart preview, plus an audible onset-check WAV."""
import html
import json
import numpy as np
import soundfile as sf

def create_preview(folder, charts, tempo, lead, metadata):
    y,sr = sf.read(folder/"audio"/"song.wav",dtype="float32",always_2d=True)
    for instrument, parts in charts.items():
        clicks = np.zeros(len(y),dtype="float32")
        frequency={"guitar":880,"bass":440,"drums":1320,"keys":660}[instrument]
        t=np.arange(int(0.025*sr))/sr
        pulse=np.sin(2*np.pi*frequency*t)*np.exp(-t*150)*0.18
        for note in parts["expert"]:
            start=round((note.start+lead)*sr)
            end=min(len(clicks),start+len(pulse))
            if start>=0 and end>start:
                clicks[start:end]+=pulse[:end-start]
        audit=y*0.62+clicks[:,None]
        audit/=max(1.0,float(np.max(np.abs(audit)))/0.98)
        sf.write(folder/"audio"/f"timing-audit-{instrument}.wav",audit,sr,subtype="PCM_16")
    data={i:{d:[{"t":n.start+lead,"end":n.end+lead,"lanes":n.lanes,"c":n.confidence} for n in notes] for d,notes in diffs.items()} for i,diffs in charts.items()}
    payload=json.dumps({"charts":data,"beats":[beat+lead for beat in tempo.beats],"meter":tempo.numerator,"lead":lead}).replace("<","\\u003c")
    title=html.escape(metadata["title"])
    artist=html.escape(metadata["artist"])
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Chart review</title>
<style>body{background:#0b111c;color:#e4ebf5;font:16px system-ui;margin:32px auto;padding:0 14px;max-width:1000px}h1{margin-bottom:4px}p{color:#a8b8cd}button,select{font:inherit;padding:8px 14px;background:#24344b;color:white;border:1px solid #526780;border-radius:8px}button{cursor:pointer}canvas{width:100%;height:auto;aspect-ratio:11/7;background:linear-gradient(#10192a,#080d16);border:1px solid #2b3d57;border-radius:12px;margin:18px 0;box-shadow:0 18px 50px #0008}audio{width:100%;margin-top:12px}.badge{color:#75dac5}.controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap}label{margin-right:12px}#scroll-wrap{height:70vh;min-height:320px;overflow:auto;overscroll-behavior:contain;touch-action:pan-x pan-y;background:#0b111c;border:1px solid #2b3d57;border-radius:12px;margin:18px 0}#scroll-chart{display:block;width:600px;height:auto;aspect-ratio:auto;max-width:none;margin:0;border:0;border-radius:0;box-shadow:none}.scroll-lane-head{position:sticky;top:0;z-index:1;display:grid;grid-template-columns:100px repeat(5,100px);width:600px;background:#17283d;border-bottom:2px solid #52647d;text-align:center;font-size:14px}.scroll-lane-head span{padding:10px 2px}.scroll-lane-head span:not(:first-child){border-left:1px solid #52647d}@media(max-width:600px){body{margin:14px auto;padding:0 10px}h1{font-size:1.45rem}.controls{display:grid;grid-template-columns:1fr 1fr;gap:8px}.controls label{margin:0}.controls select,.controls button{width:100%;min-height:44px;padding:8px 6px}#scroll-wrap{height:68vh;min-height:300px}audio{min-height:44px}}</style>
<h1>__TITLE__</h1><p>__ARTIST__ · Draft chart review</p><p class="badge">Original timing preserved · Expert → Hard → Medium → Easy</p>
<div class="controls"><label>View <select id="view"><option value="highway">Live highway</option><option value="scroll">Scrollable chart</option></select></label><label>Instrument <select id="inst"></select></label><label>Difficulty <select id="diff"><option>expert</option><option>hard</option><option>medium</option><option>easy</option></select></label><label>Audio <select id="mode"><option value="song">Song</option><option value="audit">Song + selected-instrument clicks</option></select></label><label>Highway spacing <select id="zoom"><option value="2.6">Spread out</option><option value="3.5">Normal</option><option value="4.5">Far view</option></select></label><button id="back">−5 seconds</button><button id="toggle">Play / Pause</button><label>Speed <select id="speed"><option value="1">1×</option><option value=".75">0.75×</option><option value=".5">0.5×</option></select></label></div>
<div id="highway-view"><canvas id="chart" width="1100" height="700"></canvas></div>
<div id="scroll-wrap" hidden><div class="scroll-lane-head"><span>Song time</span><span id="scroll-lane-0">Green</span><span id="scroll-lane-1">Red</span><span id="scroll-lane-2">Yellow</span><span id="scroll-lane-3">Blue</span><span id="scroll-lane-4">Orange</span></div><canvas id="scroll-chart" width="600" aria-label="Scrollable chart lanes by song time"></canvas></div><audio id="audio" controls src="audio/song.wav"></audio>
<p id="view-help">Notes travel down the highway and cross the white strike line when played. Bright beat lines show measure starts. Switch to click audio to hear Expert onsets, slow playback for dense passages, and scrub or jump back to repeat a section.</p><p id="stats"></p>
<script>const payload=__DATA__,data=payload.charts,beats=payload.beats,meter=payload.meter,lead=payload.lead;const inst=document.getElementById('inst'),diff=document.getElementById('diff'),audio=document.getElementById('audio'),canvas=document.getElementById('chart'),ctx=canvas.getContext('2d'),mode=document.getElementById('mode'),speed=document.getElementById('speed'),zoom=document.getElementById('zoom'),view=document.getElementById('view'),scrollWrap=document.getElementById('scroll-wrap'),scrollCanvas=document.getElementById('scroll-chart'),scrollCtx=scrollCanvas.getContext('2d');Object.keys(data).forEach(i=>{const o=document.createElement('option');o.textContent=i;inst.append(o)});function setAudio(){const t=audio.currentTime,playing=!audio.paused;audio.src='audio/'+(mode.value==='audit'?'timing-audit-'+inst.value+'.wav':'song.wav');audio.onloadedmetadata=()=>{audio.currentTime=t;audio.playbackRate=+speed.value;if(playing)audio.play()}}mode.onchange=setAudio;inst.onchange=()=>{if(mode.value==='audit')setAudio();renderScroll()};diff.onchange=()=>renderScroll();speed.onchange=()=>audio.playbackRate=+speed.value;zoom.onchange=()=>lookAhead=+zoom.value;view.onchange=()=>{const scrolling=view.value==='scroll';document.getElementById('highway-view').hidden=scrolling;scrollWrap.hidden=!scrolling;document.getElementById('view-help').textContent=scrolling?'Scroll vertically through the chart; song time and lane colors stay labeled. Swipe sideways if needed, then screenshot a section to share visual feedback.':'Notes travel down the highway and cross the white strike line when played. Bright beat lines show measure starts. Switch to click audio to hear Expert onsets, slow playback for dense passages, and scrub or jump back to repeat a section.';if(scrolling)renderScroll();else requestAnimationFrame(draw)};document.getElementById('back').onclick=()=>audio.currentTime=Math.max(0,audio.currentTime-5);document.getElementById('toggle').onclick=()=>audio.paused?audio.play():audio.pause();document.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;if(e.code==='Space'){e.preventDefault();audio.paused?audio.play():audio.pause()}if(e.code==='ArrowLeft')audio.currentTime=Math.max(0,audio.currentTime-5);if(e.code==='ArrowRight')audio.currentTime=Math.min(audio.duration||Infinity,audio.currentTime+5)});
const colors=['#65df7b','#ff5864','#f8d45d','#4c9dff','#ff973d'],W=1100,H=700,horizon=48,strike=590,topWidth=300,bottomWidth=820;let lookAhead=+zoom.value;function geom(y){const p=Math.max(0,Math.min(1,(y-horizon)/(strike-horizon))),width=topWidth+(bottomWidth-topWidth)*p;return {left:(W-width)/2,width}}function yFor(t,time){return strike-(t-time)/lookAhead*(strike-horizon)}function laneX(lane,y){const g=geom(y);return g.left+(lane+.5)*g.width/5}function lineAt(y,color,width=1){const g=geom(y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(g.left,y);ctx.lineTo(g.left+g.width,y);ctx.stroke()}function draw(){const time=audio.currentTime,notes=data[inst.value][diff.value];ctx.clearRect(0,0,W,H);const floor=ctx.createLinearGradient(0,horizon,0,strike);floor.addColorStop(0,'#111d31');floor.addColorStop(1,'#17283d');const bottom=geom(strike),top=geom(horizon);ctx.fillStyle=floor;ctx.beginPath();ctx.moveTo(top.left,horizon);ctx.lineTo(top.left+top.width,horizon);ctx.lineTo(bottom.left+bottom.width,strike);ctx.lineTo(bottom.left,strike);ctx.closePath();ctx.fill();for(let lane=0;lane<=5;lane++){ctx.strokeStyle='#52647d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(top.left+lane*top.width/5,horizon);ctx.lineTo(bottom.left+lane*bottom.width/5,strike);ctx.stroke()}beats.forEach((beat,index)=>{const y=yFor(beat,time);if(y<horizon||y>strike+20)return;lineAt(y,index%meter===0?'#95aac5':'#344760',index%meter===0?3:1)});lineAt(strike,'#ffffff',6);ctx.shadowBlur=0;const labels=inst.value==='drums'?['Kick','Snare','Hi-hat','Blue','Green']:['Green','Red','Yellow','Blue','Orange'];ctx.font='16px system-ui';ctx.textAlign='center';for(let lane=0;lane<5;lane++){const x=laneX(lane,strike);ctx.fillStyle=colors[lane];ctx.beginPath();ctx.arc(x,strike,22,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dfe9f5';ctx.fillText(labels[lane],x,642)}for(const n of notes){const rawStart=yFor(n.t,time),rawEnd=yFor(n.end,time);if(rawStart<horizon-30||rawEnd>strike+45)continue;const y=Math.min(strike,rawStart),endY=Math.max(horizon,rawEnd);for(const lane of n.lanes){if(n.end-n.t>.15&&endY<y){const x1=laneX(lane,y),x2=laneX(lane,endY),w1=5+10*(y-horizon)/(strike-horizon),w2=5+10*(endY-horizon)/(strike-horizon);ctx.globalAlpha=.25+.5*n.c;ctx.fillStyle=colors[lane];ctx.beginPath();ctx.moveTo(x1-w1,y);ctx.lineTo(x1+w1,y);ctx.lineTo(x2+w2,endY);ctx.lineTo(x2-w2,endY);ctx.closePath();ctx.fill()}const x=laneX(lane,y),size=7+13*Math.max(0,Math.min(1,(y-horizon)/(strike-horizon)));ctx.globalAlpha=.38+.62*n.c;ctx.fillStyle=colors[lane];ctx.strokeStyle='#f7fbff';ctx.lineWidth=2;if(Math.abs(n.t-time)<.07||(n.t<time&&n.end>time)){ctx.shadowColor=colors[lane];ctx.shadowBlur=28}ctx.beginPath();ctx.roundRect(x-size*1.35,y-size*.62,size*2.7,size*1.24,size*.55);ctx.fill();ctx.stroke();ctx.shadowBlur=0}}ctx.globalAlpha=1;ctx.textAlign='left';ctx.fillStyle='#b9c8db';ctx.fillText('NOTES APPROACH THIS LINE',bottom.left+8,strike+38);const sourceTime=Math.max(0,time-lead),local=notes.filter(n=>Math.abs(n.t-time)<=2).length/4;document.getElementById('stats').textContent=notes.length+' notes · player '+time.toFixed(2)+'s · song '+sourceTime.toFixed(2)+'s · local density '+local.toFixed(1)+'/s · '+notes.filter(n=>n.end-n.t>=.15).length+' holds · Space: play/pause · Arrows: ±5s';if(view.value==='highway')requestAnimationFrame(draw)}function renderScroll(){const notes=data[inst.value][diff.value],allNotes=Object.values(data[inst.value]).flat(),duration=Math.max(1,beats.reduce((max,beat)=>Math.max(max,beat-lead),0),allNotes.reduce((max,note)=>Math.max(max,note.end-lead),0))+1,scale=Math.min(48,15000/duration),height=Math.max(900,Math.ceil(duration*scale+40)),trackLeft=100,trackWidth=500,laneLabels=inst.value==='drums'?['Kick','Snare','Hi-hat','Blue','Green']:['Green','Red','Yellow','Blue','Orange'];laneLabels.forEach((label,lane)=>document.getElementById('scroll-lane-'+lane).textContent=label);scrollCanvas.height=height;scrollCtx.fillStyle='#0b111c';scrollCtx.fillRect(0,0,600,height);for(let lane=0;lane<5;lane++){const x=trackLeft+lane*trackWidth/5;scrollCtx.fillStyle=lane%2?'#101a2a':'#131f31';scrollCtx.fillRect(x,0,trackWidth/5,height);scrollCtx.strokeStyle='#344760';scrollCtx.beginPath();scrollCtx.moveTo(x,0);scrollCtx.lineTo(x,height);scrollCtx.stroke()}scrollCtx.strokeStyle='#52647d';scrollCtx.beginPath();scrollCtx.moveTo(trackLeft+trackWidth,0);scrollCtx.lineTo(trackLeft+trackWidth,height);scrollCtx.stroke();for(let second=0;second<=duration;second++){const y=30+second*scale;scrollCtx.strokeStyle='#28384e';scrollCtx.beginPath();scrollCtx.moveTo(0,y);scrollCtx.lineTo(600,y);scrollCtx.stroke();scrollCtx.fillStyle='#b9c8db';scrollCtx.font='13px system-ui';scrollCtx.textAlign='left';scrollCtx.fillText(Math.floor(second/60)+':'+String(second%60).padStart(2,'0'),8,y-3)}beats.forEach((beat,index)=>{const y=30+(beat-lead)*scale;if(y<30||y>height)return;scrollCtx.strokeStyle=index%meter===0?'#95aac5':'#40516a';scrollCtx.lineWidth=index%meter===0?2:1;scrollCtx.beginPath();scrollCtx.moveTo(0,y);scrollCtx.lineTo(600,y);scrollCtx.stroke()});for(const note of notes){const y=30+(note.t-lead)*scale,endY=30+(note.end-lead)*scale;for(const lane of note.lanes){const center=trackLeft+(lane+.5)*trackWidth/5;scrollCtx.globalAlpha=.35+.65*note.c;scrollCtx.fillStyle=colors[lane];if(note.end-note.t>=.09&&endY-y>5)scrollCtx.fillRect(center-25,y,50,endY-y);scrollCtx.fillRect(center-38,y-8,76,16);scrollCtx.strokeStyle='#f7fbff';scrollCtx.lineWidth=1.5;scrollCtx.strokeRect(center-38,y-8,76,16)}}scrollCtx.globalAlpha=1;scrollCtx.textAlign='left'}renderScroll();draw();</script></html>'''
    page=page.replace("n.end-n.t>.15","n.end-n.t>=.09").replace("n.end-n.t>=.15","n.end-n.t>=.09")
    (folder/"review.html").write_text(page.replace("__TITLE__",title).replace("__ARTIST__",artist).replace("__DATA__",payload),encoding="utf-8")
